def transform(g):
    H=len(g); W=len(g[0]); c=4
    border=g[0][c]
    hrows=[r for r in range(H) if len(set(g[r]))==1]
    vcols=[cc for cc in range(W) if all(g[r][cc]==border for r in range(H))]
    def grp(l):
        out=[];cur=[l[0]]
        for x in l[1:]:
            if x==cur[-1]+1: cur.append(x)
            else: out.append(cur);cur=[x]
        out.append(cur);return out
    rg=grp([r for r in range(H) if r not in hrows])
    cg=grp([cc for cc in range(W) if cc not in vcols])
    from collections import Counter
    blocks={}
    for bi,rr in enumerate(rg):
        cnt=Counter(g[r][cc] for r in rr for cc in cg[0] if g[r][cc]!=0)
        blocks[bi]=cnt.most_common(1)[0][0]
    # pattern color: any nonzero color not equal to any block color
    allc=set(g[r][cc] for r in range(H) for cc in range(W) if g[r][cc]!=0)-set(blocks.values())
    pc=allc.pop()
    # locate its cell
    pat=None
    for rr in rg:
        for cc_ in cg:
            sub=[[g[r][x] for x in cc_] for r in rr]
            if any(pc in row for row in sub):
                s=set((r,i) for r in range(4) for i in range(4) if sub[r][i]==pc)
                pat=[[1 if (r,i) in s else 0 for i in range(4)] for r in range(4)]
    out=[row[:] for row in g]
    for bi,rr in enumerate(rg):
        for r in rr:
            for cc_ in cg:
                for dr in range(4):
                    for dc in range(4):
                        out[rr[dr]][cc_[dc]]=blocks[bi]*pat[dr][dc]
    return out
